    combined.update(dict_b)
    zipped_vals = zip(*combined.values())
    keys = list(combined.keys())

    out = []
    for i, zv in enumerate(zipped_vals):
        obj = {k: v_ for (k,v_) in zip(keys, zv)}
        out.append(obj)

